using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using SenorArroz.Domain.Entities;using SenorArroz.Domain.Enums;
namespace SenorArroz.Infrastructure.Data.Configurations;
public class WhatsAppOrderDraftConfiguration:IEntityTypeConfiguration<WhatsAppOrderDraft>{public void Configure(EntityTypeBuilder<WhatsAppOrderDraft>b){b.ToTable("whatsapp_order_draft");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id");b.Property(x=>x.ConversationId).HasColumnName("conversation_id");b.Property(x=>x.CustomerId).HasColumnName("customer_id");b.Property(x=>x.BranchId).HasColumnName("branch_id");b.Property(x=>x.OrderType).HasColumnName("order_type").HasConversion<string>();b.Property(x=>x.AddressId).HasColumnName("address_id");b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>();b.Property(x=>x.PaymentMethod).HasColumnName("payment_method").HasMaxLength(30);b.Property(x=>x.PaymentMethodId).HasColumnName("payment_method_id");b.Property(x=>x.CashReceived).HasColumnName("cash_received");b.Property(x=>x.ChangeAmount).HasColumnName("change_amount");b.Property(x=>x.Subtotal).HasColumnName("subtotal");b.Property(x=>x.DeliveryFee).HasColumnName("delivery_fee");b.Property(x=>x.DiscountTotal).HasColumnName("discount_total");b.Property(x=>x.Total).HasColumnName("total");b.Property(x=>x.Notes).HasColumnName("notes").HasMaxLength(1000);b.Property(x=>x.ConfirmedAt).HasColumnName("confirmed_at");b.Property(x=>x.CancelledAt).HasColumnName("cancelled_at");b.Property(x=>x.CancelledReason).HasColumnName("cancelled_reason").HasMaxLength(500);b.Property(x=>x.OrderId).HasColumnName("order_id");b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();b.Property(x=>x.CreatedAt).HasColumnName("created_at");b.Property(x=>x.UpdatedAt).HasColumnName("updated_at");b.HasOne(x=>x.Conversation).WithMany().HasForeignKey(x=>x.ConversationId).OnDelete(DeleteBehavior.Cascade);b.HasOne(x=>x.Customer).WithMany().HasForeignKey(x=>x.CustomerId).OnDelete(DeleteBehavior.SetNull);b.HasOne(x=>x.Branch).WithMany().HasForeignKey(x=>x.BranchId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.Address).WithMany().HasForeignKey(x=>x.AddressId).OnDelete(DeleteBehavior.SetNull);b.HasOne(x=>x.Order).WithMany().HasForeignKey(x=>x.OrderId).OnDelete(DeleteBehavior.SetNull);b.HasIndex(x=>x.ConversationId).HasFilter("status IN ('Building','AwaitingCustomerData','AwaitingAddress','AwaitingPayment','ReadyForConfirmation')").IsUnique();}}
public class WhatsAppOrderDraftItemConfiguration:IEntityTypeConfiguration<WhatsAppOrderDraftItem>{public void Configure(EntityTypeBuilder<WhatsAppOrderDraftItem>b){b.ToTable("whatsapp_order_draft_item");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id");b.Property(x=>x.DraftId).HasColumnName("draft_id");b.Property(x=>x.ProductId).HasColumnName("product_id");b.Property(x=>x.Quantity).HasColumnName("quantity");b.Property(x=>x.UnitPrice).HasColumnName("unit_price");b.Property(x=>x.Notes).HasColumnName("notes").HasMaxLength(500);b.Property(x=>x.SelectedOptions).HasColumnName("selected_options").HasColumnType("jsonb");b.Property(x=>x.Subtotal).HasColumnName("subtotal");b.Property(x=>x.CreatedAt).HasColumnName("created_at");b.Property(x=>x.UpdatedAt).HasColumnName("updated_at");b.HasOne(x=>x.Draft).WithMany(x=>x.Items).HasForeignKey(x=>x.DraftId).OnDelete(DeleteBehavior.Cascade);b.HasOne(x=>x.Product).WithMany().HasForeignKey(x=>x.ProductId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.DraftId,x.ProductId});}}
public class WhatsAppOrderConfirmationConfiguration:IEntityTypeConfiguration<WhatsAppOrderConfirmation>{public void Configure(EntityTypeBuilder<WhatsAppOrderConfirmation>b){b.ToTable("whatsapp_order_confirmation");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id");b.Property(x=>x.DraftId).HasColumnName("draft_id");b.Property(x=>x.ConfirmationMessageId).HasColumnName("confirmation_message_id");b.Property(x=>x.OrderId).HasColumnName("order_id");b.Property(x=>x.ConfirmedAt).HasColumnName("confirmed_at");b.Property(x=>x.CreatedAt).HasColumnName("created_at");b.Property(x=>x.UpdatedAt).HasColumnName("updated_at");b.HasIndex(x=>new{x.DraftId,x.ConfirmationMessageId}).IsUnique();b.HasOne(x=>x.Draft).WithMany(x=>x.Confirmations).HasForeignKey(x=>x.DraftId).OnDelete(DeleteBehavior.Cascade);b.HasOne(x=>x.ConfirmationMessage).WithMany().HasForeignKey(x=>x.ConfirmationMessageId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.Order).WithMany().HasForeignKey(x=>x.OrderId).OnDelete(DeleteBehavior.SetNull);}}
